"""Five extensions generated by the CLI, proven decoupled, cooperating and isolated.

`tickets` and `invoices` (modules), `activity_digest` (plugin), `midnight`
(theme) and `outbound_webhooks` (connector) came out of `dev.py make ...`; the
only hand-written parts are their business rules. None imports another: they
react to model events and talk through the internal proxy.
"""

import os
import re
from typing import Any

import pytest
from starlette.testclient import TestClient

from craft.container.internal_proxy import InternalProxyError
from craft.facades import DB, Proxy, View
from craft.support.translation import current_locale

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
GENERATED = {
    "tickets": "modules", "invoices": "modules", "activity_digest": "plugins",
    "midnight": "themes", "outbound_webhooks": "connectors",
}
KINDS = {"tickets": "module", "invoices": "module", "activity_digest": "plugin", "midnight": "theme", "outbound_webhooks": "connector"}


@pytest.fixture
def manager(crm: Any) -> Any:
    return crm.make("extensions")


@pytest.fixture
def client(crm: Any) -> TestClient:
    from bootstrap.app import asgi_app

    return TestClient(asgi_app, follow_redirects=False)


@pytest.fixture
def connector(crm: Any) -> Any:
    """The connector's client with its transport restored after the test."""
    from app.connectors.outbound_webhooks.services.outbound_webhooks_client import OutboundWebhooksClient

    instance = crm.make(OutboundWebhooksClient)
    original = instance._transport
    yield instance
    instance._transport = original


def _digest() -> dict:
    return Proxy.call("activity_digest", "snapshot")


class TestGeneratedAndDecoupled:
    @pytest.mark.parametrize("slug", sorted(GENERATED))
    def test_the_extension_is_active_serving_and_of_its_kind(self, manager: Any, slug: str) -> None:
        assert manager.manifests()[slug].kind.value == KINDS[slug]
        assert manager.state(slug).value == "active"
        assert manager.availability(slug).value == "serving"

    @pytest.mark.parametrize("slug", ["tickets", "invoices"])
    def test_a_module_is_born_with_its_table_from_its_own_migration(self, slug: str) -> None:
        assert DB.table(f"{slug}_records").count() >= 0
        names = os.listdir(os.path.join(ROOT, "app", "modules", slug, "migrations"))
        assert any(name.endswith(f"_create_{slug}_records_table.py") for name in names)

    def test_the_connector_is_born_with_its_delivery_log(self) -> None:
        assert DB.table("outbound_webhooks_deliveries").count() >= 0

    @pytest.mark.parametrize("slug", sorted(GENERATED))
    def test_no_generated_extension_imports_another_extension(self, slug: str) -> None:
        directory = os.path.join(ROOT, "app", GENERATED[slug], slug)
        others = "|".join(re.escape(other) for other in GENERATED if other != slug)
        pattern = re.compile(rf"^\s*(from|import)\s+app\.(modules|plugins|themes|connectors)\.({others}|companies|contacts|deals|activities|dashboard)\b", re.M)
        for folder, _dirs, files in os.walk(directory):
            for name in files:
                if name.endswith(".py"):
                    with open(os.path.join(folder, name), encoding="utf-8") as handle:
                        assert not pattern.search(handle.read()), f"{folder}/{name} imports another extension"

    @pytest.mark.parametrize("slug", ["tickets", "invoices"])
    def test_the_module_keeps_its_title_in_three_locales(self, slug: str) -> None:
        rows = DB.table("translations").where("key", f"{slug}.index.title").get()
        assert {row["locale"] for row in rows} == {"en", "pt-BR", "es"}


class TestCooperationWithoutCoupling:
    def test_a_ticket_and_an_invoice_are_counted_by_the_plugin_through_events(self) -> None:
        before = _digest()
        Proxy.call("tickets", "open", "Printer jams")
        Proxy.call("invoices", "issue", "March services")
        after = _digest()
        assert after["tickets_records"] == before.get("tickets_records", 0) + 1
        assert after["invoices_records"] == before.get("invoices_records", 0) + 1

    def test_every_created_record_is_forwarded_by_the_connector_and_logged(self) -> None:
        before = DB.table("outbound_webhooks_deliveries").count()
        Proxy.call("tickets", "open", "Cannot log in")
        assert DB.table("outbound_webhooks_deliveries").count() == before + 1

    def test_the_connector_uses_the_injected_transport(self, connector: Any) -> None:
        sent: list = []
        connector._transport = lambda event, payload: (sent.append((event, payload)) or {"status": "queued"})
        Proxy.call("invoices", "issue", "April services")
        assert sent == [("record.created", {"table": "invoices_records"})]
        assert DB.table("outbound_webhooks_deliveries").where("status", "queued").count() >= 1

    def test_the_summary_counts_what_the_service_opened(self) -> None:
        before = Proxy.call("tickets", "summary")["items"]
        Proxy.call("tickets", "open", "Another")
        assert Proxy.call("tickets", "summary")["items"] == before + 1

    def test_a_blank_name_is_refused_before_anything_is_written(self) -> None:
        before = Proxy.call("tickets", "summary")["items"]
        with pytest.raises(ValueError):
            Proxy.call("tickets", "open", "   ")
        assert Proxy.call("tickets", "summary")["items"] == before


class TestFaultIsolation:
    def test_a_failing_connector_never_breaks_the_business_write_or_the_plugin(self, connector: Any, manager: Any) -> None:
        def broken(event: str, payload: dict) -> dict:
            raise RuntimeError("outside service down")

        connector._transport = broken
        before = _digest().get("tickets_records", 0)
        for index in range(8):
            assert Proxy.call("tickets", "open", f"Resilient {index}") > 0
        assert _digest()["tickets_records"] == before + 8
        # Reactivating closes the connector's breaker so later tests start clean.
        manager.deactivate("outbound_webhooks")
        manager.activate("outbound_webhooks")


class TestLifecycleAtRuntime:
    def test_a_deactivated_plugin_stops_counting_and_is_refused_on_the_proxy(self, manager: Any) -> None:
        manager.deactivate("activity_digest")
        try:
            with pytest.raises(InternalProxyError):
                Proxy.call("activity_digest", "snapshot")
            Proxy.call("tickets", "open", "While the plugin is off")
        finally:
            manager.activate("activity_digest")
        assert isinstance(_digest(), dict)

    def test_a_deactivated_connector_stops_forwarding_and_resumes_when_reactivated(self, manager: Any) -> None:
        count = lambda: DB.table("outbound_webhooks_deliveries").count()  # noqa: E731
        manager.deactivate("outbound_webhooks")
        try:
            before = count()
            Proxy.call("tickets", "open", "Connector off")
            assert count() == before
        finally:
            manager.activate("outbound_webhooks")
        before = count()
        Proxy.call("tickets", "open", "Connector on")
        assert count() == before + 1

    def test_uninstalling_keeps_the_rows(self, manager: Any) -> None:
        Proxy.call("invoices", "issue", "Kept forever")
        rows = DB.table("invoices_records").count()
        manager.deactivate("invoices")
        manager.uninstall("invoices")
        try:
            assert DB.table("invoices_records").count() == rows
        finally:
            manager.install("invoices")
            manager.activate("invoices")


class TestWebhookAndTheme:
    def test_the_inbound_webhook_answers_without_csrf_and_stops_when_the_connector_is_off(self, client: TestClient, manager: Any) -> None:
        url = "/api/webhooks/outbound-webhooks/ack"
        answer = client.post(url)
        assert answer.status_code == 200 and answer.json() == {"acknowledged": True}
        manager.deactivate("outbound_webhooks")
        try:
            assert client.post(url).status_code != 200
        finally:
            manager.activate("outbound_webhooks")
        assert client.post(url).status_code == 200

    def test_the_theme_overrides_the_module_view_at_runtime_and_can_be_dropped(self, crm: Any) -> None:
        view = crm.make("view")
        data = {"summary": {"items": 3}}
        try:
            view.set_theme_resolver(lambda: "midnight")
            assert 'data-theme="midnight"' in View.render("tickets::index", data)
            view.set_theme_resolver(None)
            assert 'data-theme="midnight"' not in View.render("tickets::index", data)
        finally:
            view.set_theme_resolver(None)

    def test_the_module_screen_renders_translated_with_a_plural(self) -> None:
        token = current_locale.set("pt-BR")
        try:
            one = View.render("tickets::index", {"summary": {"items": 1}})
            many = View.render("tickets::index", {"summary": {"items": 5}})
        finally:
            current_locale.reset(token)
        assert 'data-items="1"' in one and "1 chamado<" in one
        assert 'data-items="5"' in many and "5 chamados<" in many
